function CountVowels(s: string): int
    requires s != null
    ensures Result >= 0
{
    var c := 0;
    var i := 0;
    while i < s.Length
        invariant 0 <= i <= s.Length
        invariant c == CountVowels(s.Substring(0, i))
    {
        if IsVowel(s[i]) {
            c := c + 1;
        }
        i := i + 1;
    }
    return c;
}

function IsVowel(c: char): bool
    requires 'a' <= c && c <= 'z' || 'A' <= c && c <= 'Z'
{
